// Hashes the key, finds the matching item in the bucket chain, unlinks it, clears and deletes it, decrements the count, and returns whether it was removed.
// @fnv 0x00405430
bool NiTMap_S::RemoveKey(unsigned int key)
{
    unsigned int uiIndex = KeyToHashIndex(key);
    MapItem_S* pkItem = m_ppkHashTable[uiIndex];
    if (pkItem)
    {
        if (IsKeysEqual(key, pkItem->m_key))
        {
            m_ppkHashTable[uiIndex] = pkItem->m_pkNext;
            ClearValue(pkItem);
            DeleteItem(pkItem);
            m_uiCount--;
            return true;
        }
        else
        {
            MapItem_S* pkPrev = pkItem;
            MapItem_S* pkCurr = pkPrev->m_pkNext;
            while (pkCurr && !IsKeysEqual(key, pkCurr->m_key))
            {
                pkPrev = pkCurr;
                pkCurr = pkCurr->m_pkNext;
            }
            if (pkCurr)
            {
                pkPrev->m_pkNext = pkCurr->m_pkNext;
                ClearValue(pkCurr);
                DeleteItem(pkCurr);
                m_uiCount--;
                return true;
            }
        }
    }
    return false;
}

